package expand

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"

	"github.com/advanced-security/codeql-abom/internal/ingest"
	"github.com/advanced-security/codeql-abom/internal/runner"
	"github.com/advanced-security/codeql-abom/internal/store"
)

// The SARIF the CodeQL CLI actually emits, generated by `database analyze`. Hand-written SARIF
// would agree with whatever the reader expects and prove nothing.
const fixtureFindings = "testdata/findings.sarif"

// fakeAnalyzer stands in for `database analyze`, recording what it was asked to run so the test
// can check the lane received queries rather than a suite it cannot execute.
type fakeAnalyzer struct {
	mu      sync.Mutex
	targets [][]string
	err     error
}

func (a *fakeAnalyzer) AnalyzeQueries(
	_ context.Context, _ string, targets []string, sarifPath string,
) error {
	a.mu.Lock()
	a.targets = append(a.targets, append([]string(nil), targets...))
	err := a.err
	a.mu.Unlock()
	if err != nil {
		return err
	}
	body, readErr := os.ReadFile(fixtureFindings)
	if readErr != nil {
		return readErr
	}
	if err := os.MkdirAll(filepath.Dir(sarifPath), 0o755); err != nil {
		return err
	}
	return os.WriteFile(sarifPath, body, 0o644)
}

// findingsHarness binds one tier to a suite that mixes both lanes, which is what the shipped
// `direct` default does.
func findingsHarness(t *testing.T) (*harness, *fakeAnalyzer) {
	t.Helper()
	h := newHarness(t)
	h.expander.Resolver = &fakeResolver{
		queries: []string{"/q/AbomEdges.ql", "/q/Unpinned.ql"},
		meta: map[string]runner.Metadata{
			"/q/AbomEdges.ql": {ID: "abom/edges", Tags: ingest.TagEdges},
			"/q/Unpinned.ql":  {ID: "actions/unpinned-tag", Kind: "problem"},
		},
	}
	a := &fakeAnalyzer{}
	h.expander.Analyzer = a
	for _, tier := range []string{store.TierDirect, store.TierTransitive} {
		if err := h.store.SetTierSuites(tier, []string{"mixed.qls"}); err != nil {
			t.Fatalf("SetTierSuites: %v", err)
		}
	}
	return h, a
}

func countFindings(t *testing.T, h *harness) int {
	t.Helper()
	var n int
	if err := h.store.DB().QueryRow(`SELECT COUNT(*) FROM abom_finding`).Scan(&n); err != nil {
		t.Fatalf("counting findings: %v", err)
	}
	return n
}

// runBound names no query path, so the round runs what each tier is bound to.
func runBound(t *testing.T, h *harness) Stats {
	t.Helper()
	stats, err := h.expander.Run(context.Background(),
		Options{WorkDir: t.TempDir(), Limit: 10})
	if err != nil {
		t.Fatalf("Run: %v", err)
	}
	return stats
}

// The defect this lane exists to fix: the `direct` default bound a findings suite and the
// planner dropped it, so the binding promised a security pass the crawl never ran.
func TestABoundFindingsSuiteProducesFindingsRatherThanSilence(t *testing.T) {
	h, a := findingsHarness(t)
	h.enqueue(item("actions", "checkout", "", 1))

	runBound(t, h)

	if got := countFindings(t, h); got == 0 {
		t.Fatal("a crawl bound to a findings suite recorded no findings")
	}
	if len(a.targets) != 1 {
		t.Fatalf("analyze ran %d times, want once per database", len(a.targets))
	}
	if len(a.targets[0]) != 1 || a.targets[0][0] != "/q/Unpinned.ql" {
		t.Errorf("analyze ran %v, want only the queries this lane can execute", a.targets[0])
	}
}

// `database analyze` cannot execute a `@kind graph` query, so passing it the suite that selected
// both would fail the whole pass. The two lanes read the same suite and take different members.
func TestTheBqrsLaneStillRunsWhenASuiteMixesBoth(t *testing.T) {
	h, _ := findingsHarness(t)
	h.enqueue(item("actions", "checkout", "", 1))

	stats := runBound(t, h)

	if stats.Edges == 0 {
		t.Error("the findings lane displaced the dependency edges the crawl exists to collect")
	}
}

// Edges settle the frontier; findings only enrich. Losing a repository's place in the crawl
// because an upstream security query failed would strand its dependencies.
func TestAFailedFindingsPassKeepsTheDependencyEdges(t *testing.T) {
	h, a := findingsHarness(t)
	a.err = os.ErrPermission
	h.enqueue(item("actions", "checkout", "", 1))

	stats := runBound(t, h)

	if stats.Edges != 0 {
		t.Errorf("edges = %d; a failed analyze must fail the job, not half-settle it", stats.Edges)
	}
	if stats.Failed == 0 {
		t.Error("a failed analyze was not reported as a failure")
	}
}

// `database analyze` is built to take a suite, and the suite carries selection that an expanded
// file list drops. Only a suite that mixes lanes has to be named query by query.
func TestASuiteThatIsAllFindingsIsRunAsASuite(t *testing.T) {
	e := &Expander{Resolver: &fakeResolver{
		queries: []string{"/q/Unpinned.ql", "/q/Injection.ql"},
		meta: map[string]runner.Metadata{
			"/q/Unpinned.ql":  {ID: "actions/unpinned-tag", Kind: "problem"},
			"/q/Injection.ql": {ID: "actions/argument-injection", Kind: "path-problem"},
		},
	}}

	planned, err := e.plan(context.Background(), Options{Suite: "abom-findings.qls"})
	if err != nil {
		t.Fatalf("plan: %v", err)
	}
	if len(planned.findings) != 1 || planned.findings[0] != "abom-findings.qls" {
		t.Errorf("findings lane %v, want the suite rather than its expanded members",
			planned.findings)
	}
}

// Which query made a claim comes from the SARIF's own rule id, not from anything ABOM passes
// in. The query run only records what was invoked, because one analyze runs many rules.
func TestEachFindingIsAttributedToItsOwnRuleFromTheSarif(t *testing.T) {
	h, _ := findingsHarness(t)
	h.enqueue(item("actions", "checkout", "", 1))

	runBound(t, h)

	rows, err := h.store.DB().Query(
		`SELECT DISTINCT rule_id FROM abom_finding ORDER BY rule_id`)
	if err != nil {
		t.Fatalf("reading rules: %v", err)
	}
	defer rows.Close()
	var rules []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			t.Fatalf("scan: %v", err)
		}
		rules = append(rules, id)
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("reading rules: %v", err)
	}
	if len(rules) == 0 {
		t.Fatal("findings landed with no rule attribution")
	}
	for _, id := range rules {
		if !strings.Contains(id, "/") {
			t.Errorf("rule %q does not look like a query id from the SARIF", id)
		}
	}

	var invoked string
	err = h.store.DB().QueryRow(
		`SELECT query_id FROM abom_query_run WHERE query_id LIKE '%.ql'`).Scan(&invoked)
	if err != nil {
		t.Fatalf("reading the findings run: %v", err)
	}
	if invoked != "/q/Unpinned.ql" {
		t.Errorf("findings run recorded as %q, want what was actually invoked", invoked)
	}
}

// A binding nothing can run is the original defect in a new place: it must be refused where an
// operator can see it, not absorbed into a crawl that quietly finds nothing.
func TestAFindingsBindingWithNoLaneIsRefusedRatherThanIgnored(t *testing.T) {
	h, _ := findingsHarness(t)
	h.expander.Analyzer = nil
	h.enqueue(item("actions", "checkout", "", 1))

	_, err := h.expander.Run(context.Background(), Options{WorkDir: t.TempDir(), Limit: 10})
	if err == nil {
		t.Fatal("a findings binding with no analyzer ran anyway")
	}
	if !strings.Contains(err.Error(), "Analyzer") {
		t.Errorf("error %q does not say what is missing", err)
	}
}
